```js
export function findConflicts(bookings) {
  if (!Array.isArray(bookings)) throw new TypeError("bookings must be an array");
  const seen = new Set();
  const parsed = [];
  for (const b of bookings) {
    if (typeof b !== "object" || b === null) throw new TypeError(...);
    if (typeof b.id !== "string" || b.id.length === 0) throw new TypeError(...);
    if (typeof b.room !== "string" || b.room.length === 0) throw new TypeError(...);
    const start = parseTimestamp(b.start);
    const end = parseTimestamp(b.end);
    if (start === null || end === null) throw new TypeError(...);
    if (!(end > start)) throw new RangeError(...);
    if (seen.has(b.id)) throw new TypeError(...);
    seen.add(b.id);
    parsed.push({ id: b.id, room: b.room, start, end });
  }
  const conflicts = [];
  for (let i = 0; i < parsed.length; i++) {
    for (let j = i + 1; j < parsed.length; j++) {
      const a = parsed[i], b = parsed[j];
      if (a.room !== b.room) continue;
      if (a.start < b.end && b.start < a.end) {
        const pair = a.id < b.id ? [a.id, b.id] : [b.id, a.id];
        conflicts.push(pair);
      }
    }
  }
  conflicts.sort((p, q) => (p[0] < q[0] ? -1 : p[0] > q[0] ? 1 : p[1] < q[1] ? -1 : p[1] > q[1] ? 1 : 0));
  return conflicts;
}
